'use strict';

// MODULES //

var canonical = require( './canonical.js' );


// MAIN //

/**
* Serializes a notebook using recursively sorted keys and a final newline.
*
* @param {Object} notebook - notebook
* @returns {string} serialized notebook
*/
function stringify( notebook ) {
	return JSON.stringify( canonical( notebook ), null, 1 )+'\n';
}


// EXPORTS //

module.exports = stringify;
